<?php require "db.php";$u=require_role("recruiter");$d=input();$title=trim($d["title"]??"");$company=trim($d["company"]??"");$location=trim($d["location"]??"");$desc=trim($d["description"]??"");$salary=(float)($d["salary"]??0);$cat=$d["category"]??"IT";$type=$d["job_type"]??"Full Time";if(!$title||!$company||!$location||!$desc||$salary<0){http_response_code(422);done(["success"=>false,"message"=>"Complete all job fields."]);}$s=$pdo->prepare("INSERT INTO jobs(recruiter_id,title,company,location,salary,category,job_type,description) VALUES(?,?,?,?,?,?,?,?)");$s->execute([$u["id"],$title,$company,$location,$salary,$cat,$type,$desc]);done(["success"=>true,"message"=>"Job published successfully."]);?>